function drawObjects(){const visible=objects.filter(o=>Math.abs(o.x-camera.x)<W*.75+150&&Math.abs(o.y-camera.y)<H*.75+150).sort((a,b)=>a.y-b.y);for(const o of visible){let p=screen(o);if(o.type==='tree')drawTree(p.x,p.y,o.scale,o.tone);else if(o.type==='rock')drawRock(p.x,p.y,o.scale,o.tone);else drawFlower(p.x,p.y,o.tone)}}
const greens=['#31583d','#3d6645','#46724c','#355d43'];
function drawTree(x,y,s,t){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#25392e66';ctx.beginPath();ctx.ellipse(3,8,27,13,0,0,7);ctx.fill();ctx.fillStyle='#755f40';ctx.fillRect(-4,-21,8,29);for(let i=0;i<3;i++){let yy=-29-i*16;ctx.fillStyle=greens[(t+i)%greens.length];ctx.beginPath();ctx.moveTo(0,yy-37);ctx.lineTo(-27+i*3,yy+12);ctx.lineTo(27-i*3,yy+12);ctx.closePath();ctx.fill();ctx.fillStyle='#83a56a45';ctx.beginPath();ctx.moveTo(0,yy-37);ctx.lineTo(-5,yy+12);ctx.lineTo(12,yy+12);ctx.closePath();ctx.fill()}ctx.restore()}
function drawRock(x,y,s,t){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#283a3066';ctx.beginPath();ctx.ellipse(3,8,20,9,0,0,7);ctx.fill();ctx.fillStyle=['#7b806e','#777c6b','#858876'][t%3];ctx.beginPath();ctx.moveTo(-17,5);ctx.lineTo(-14,-10);ctx.lineTo(-3,-20);ctx.lineTo(13,-14);ctx.lineTo(19,1);ctx.lineTo(10,8);ctx.closePath();ctx.fill();ctx.fillStyle='#c1c1a04d';ctx.beginPath();ctx.moveTo(-14,-9);ctx.lineTo(-3,-20);ctx.lineTo(5,-16);ctx.lineTo(-2,-6);ctx.closePath();ctx.fill();ctx.restore()}
function drawFlower(x,y,t){ctx.fillStyle=['#e7c980','#d99683','#e2dfb6','#c7a6ce'][t%4];ctx.fillRect(x-2,y-2,4,4);ctx.fillStyle='#9daf72';ctx.fillRect(x,y+2,1,4)}
function drawShard(o){let p=screen(o),pulse=Math.sin(now*2+o.x)*.5+.5;ctx.save();ctx.translate(p.x,p.y-12);ctx.shadowBlur=18+pulse*12;ctx.shadowColor='#f3d982';ctx.fillStyle='#f6d582';ctx.beginPath();ctx.moveTo(0,-17);ctx.lineTo(9,-2);ctx.lineTo(0,8);ctx.lineTo(-8,-2);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#fff0b1';ctx.lineWidth=1;ctx.stroke();ctx.restore()}
function drawEnemy(e){if(e.dead)return;let p=screen(e);ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#17251d88';ctx.beginPath();ctx.ellipse(2,8,e.r*1.1,8,0,0,7);ctx.fill();if(e.alert){ctx.fillStyle='#f19a73';ctx.beginPath();ctx.arc(0,-e.r-23,3,0,7);ctx.fill()}let boss=e.type==='guardian';ctx.fillStyle=e.flash>0?'#fff0c8':boss?'#596e65':e.type==='brute'?'#806450':'#9b634d';ctx.beginPath();ctx.ellipse(0,-e.r*.35,e.r*.72,e.r,0,0,7);ctx.fill();ctx.fillStyle=boss?'#93b7a3':'#d7c3a0';ctx.beginPath();ctx.arc(0,-e.r*1.25,e.r*.57,0,7);ctx.fill();ctx.fillStyle='#302c27';ctx.fillRect(-7,-e.r*1.3,4,3);ctx.fillRect(3,-e.r*1.3,4,3);ctx.strokeStyle=boss?'#d8cc99':'#b89c72';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-e.r*.65,-e.r*.1);ctx.lineTo(e.r*.95,-e.r*.7);ctx.stroke();if(e.hp<e.max||boss){ctx.fillStyle='#263128';ctx.fillRect(-22,-e.r*2.15,44,4);ctx.fillStyle=boss?'#d1b46c':'#d47d62';ctx.fillRect(-22,-e.r*2.15,44*e.hp/e.max,4)}ctx.restore()}
function drawPlayer(){let p=screen(player),ang=Math.atan2(player.faceY,player.faceX),walk=Math.sin(player.step*11)*2.6;ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#17261f88';ctx.beginPath();ctx.ellipse(0,9,17,8,0,0,7);ctx.fill();if(player.invuln>0&&Math.floor(now*15)%2===0)ctx.globalAlpha=.45;ctx.fillStyle='#26392f';ctx.beginPath();ctx.ellipse(-5,3+walk,5,10,-.1,0,7);ctx.ellipse(5,3-walk,5,10,.1,0,7);ctx.fill();ctx.fillStyle='#b97651';ctx.beginPath();ctx.ellipse(0,-9,12,15,0,0,7);ctx.fill();ctx.fillStyle='#cdbb92';ctx.beginPath();ctx.arc(0,-25,9,0,7);ctx.fill();ctx.fillStyle='#453b30';ctx.beginPath();ctx.arc(0,-28,9,Math.PI,Math.PI*2);ctx.fill();ctx.fillRect(-9,-29,18,4);ctx.strokeStyle='#e2d5b2';ctx.lineWidth=3;ctx.beginPath();let armX=Math.cos(ang)*12,armY=-10+Math.sin(ang)*8;ctx.moveTo(armX,armY);ctx.lineTo(armX+Math.cos(ang)*10,armY+Math.sin(ang)*9);ctx.stroke();if(player.attack>0){ctx.strokeStyle='#e9e9c9';ctx.lineWidth=3;ctx.shadowBlur=10;ctx.shadowColor='#e1d9a1';ctx.beginPath();ctx.arc(0,-12,37,ang-.8,ang+.8);ctx.stroke()}if(player.cast>0){ctx.shadowBlur=18;ctx.shadowColor='#ffad67';ctx.fillStyle='#ffcb73';ctx.beginPath();ctx.arc(0,-20,7,0,7);ctx.fill()}ctx.restore()}
function drawDrops(){for(let d of drops){let p=screen(d);ctx.fillStyle=d.kind==='coin'?'#f0ca6c':'#8fc190';ctx.shadowBlur=10;ctx.shadowColor=ctx.fillStyle;ctx.beginPath();ctx.arc(p.x,p.y-5,6,0,7);ctx.fill();ctx.shadowBlur=0}}
function drawProjectiles(){for(const b of projectiles){let p=screen(b);ctx.fillStyle=b.enemy?'#f78668':'#ffc56d';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=16;ctx.beginPath();ctx.arc(p.x,p.y, b.enemy?6:8,0,7);ctx.fill();ctx.shadowBlur=0}}
function drawParticles(){for(let p of particles){let s=screen(p);ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(s.x,s.y,p.size,0,7);ctx.fill()}ctx.globalAlpha=1}
function drawWeather(dt){if(weather<.15)return;ctx.strokeStyle=`rgba(190,213,218,${weather*.35})`;ctx.lineWidth=1;ctx.beginPath();for(let d of weatherDrops){d.x-=dt*90*weather;d.y+=dt*d.v*weather;if(d.y>H+20){d.y=-10;d.x=rand(0,W)}if(d.x<0)d.x=W;ctx.moveTo(d.x,d.y);ctx.lineTo(d.x-4,d.y+11)}ctx.stroke()}
function render(dt){ctx.clearRect(0,0,W,H);drawGround();drawObjects();for(const s of shards)if(!s.got)drawShard(s);drawDrops();for(const e of enemies)drawEnemy(e);drawProjectiles();drawPlayer();drawParticles();drawWeather(dt);let gradient=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.17,W/2,H/2,Math.max(W,H)*.77);gradient.addColorStop(0,'#15231d00');gradient.addColorStop(1,'#0b151755');ctx.fillStyle=gradient;ctx.fillRect(0,0,W,H);drawMini()}
function drawMini(){let w=mini.clientWidth,h=mini.clientHeight;if(!w||!h)return;mctx.clearRect(0,0,w,h);mctx.fillStyle='#203c32';mctx.fillRect(0,0,w,h);mctx.save();mctx.translate(w/2-player.x/WORLD*w,h/2-player.y/WORLD*h);mctx.scale(w/WORLD,h/WORLD);mctx.fillStyle='#648e81';mctx.beginPath();for(let y=0;y<=WORLD;y+=25){let x=1180+230*Math.sin(y/320)+80*Math.sin(y/105);if(y===0)mctx.moveTo(x,y);else mctx.lineTo(x,y)}mctx.lineWidth=125;mctx.strokeStyle='#57857c';mctx.stroke();for(const l of landmarks){mctx.fillStyle=l.type==='village'?'#d4b777':l.type==='shrine'?'#70c6ac':'#a4ad91';mctx.beginPath();mctx.arc(l.x,l.y,35,0,7);mctx.fill()}for(const e of enemies){if(!e.dead){mctx.fillStyle=e.type==='guardian'?'#ff8b67':'#bd6f56';mctx.fillRect(e.x-16,e.y-16,32,32)}}for(const s of shards){if(!s.got){mctx.fillStyle='#f0d47a';mctx.beginPath();mctx.arc(s.x,s.y,30,0,7);mctx.fill()}}mctx.fillStyle='#f5ecd0';mctx.beginPath();mctx.arc(player.x,player.y,29,0,7);mctx.fill();mctx.strokeStyle='#fff';mctx.lineWidth=6;mctx.stroke();mctx.restore();mctx.strokeStyle='#e6d29b66';mctx.lineWidth=1;mctx.strokeRect(.5,.5,w-1,h-1)}

