function regionNow(){return regions.find(r=>Math.hypot(player.x-r.x,player.y-r.y)<r.r)?.name||'The Greenward'}
function updateLocation(){let r=regions.find(r=>Math.hypot(player.x-r.x,player.y-r.y)<r.r)||regions[0];document.getElementById('locName').textContent=r.name;document.getElementById('locSub').textContent=r.sub+' · '+String(8+Math.floor(worldTime/60)%12).padStart(2,'0')+':'+String(Math.floor(worldTime*2)%60).padStart(2,'0')}
function showToast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove('show'),2100)}
function updateQuest(){let title=document.getElementById('questTitle'),text=document.getElementById('questText'),bar=document.getElementById('questProgress');if(state.quest===0){title.textContent='The Shards of Dawn';text.textContent=`Find the three sunshards hidden across the wilds. (${inventory.shards}/3)`;bar.style.width=(inventory.shards/3*100)+'%';if(inventory.shards>=3){state.quest=1;showToast('The shards hum in unison. Find the Drowned Shrine.')}}else if(state.quest===1){title.textContent='The Drowned Shrine';text.textContent='Reach the ancient shrine beyond Silverrun.';let d=Math.hypot(player.x-1950,player.y-1920);bar.style.width=(clamp(1-d/1500,0,1)*100)+'%';if(d<115){state.quest=2;showToast('Something stirs beneath the water…')}}else if(state.quest===2){title.textContent='The Keeper Below';text.textContent='Defeat the shrine guardian.';bar.style.width=(state.kills>0?100:25)+'%';let boss=enemies.find(e=>e.type==='guardian');if(!boss||boss.dead){state.quest=3;showToast('The river runs clear. The wilds remember you.')}}else{title.textContent='A Crown Reclaimed';text.textContent='The sunken crown is yours. The wilds are yours to explore.';bar.style.width='100%'}updateUI()}
function updateUI(){document.getElementById('hpText').textContent=Math.ceil(state.hp)+' / '+state.maxHp;document.getElementById('hpBar').style.width=100*state.hp/state.maxHp+'%';document.getElementById('stText').textContent=Math.ceil(state.st)+' / '+state.maxSt;document.getElementById('stBar').style.width=100*state.st/state.maxSt+'%';document.getElementById('xpText').textContent=state.xp+' / '+(state.level*100);document.getElementById('xpBar').style.width=(state.xp%(state.level*100))/(state.level*100)*100+'%';let near=nearInteract();document.getElementById('prompt').classList.toggle('show',!!near&&running&&!paused)}
function nearInteract(){let close=null,dd=90;for(const s of shards){if(s.got)continue;let d=dist(player,s);if(d<dd){close={kind:'shard',obj:s};dd=d}}for(const l of landmarks){let d=dist(player,l);if(d<75&&l.type==='village'&&d<dd){close={kind:'village',obj:l};dd=d}}for(const d of drops){let x=dist(player,d);if(x<dd){close={kind:'drop',obj:d};dd=x}}if(close){document.getElementById('prompt').textContent=close.kind==='shard'?'Press E to claim Sunshard':close.kind==='drop'?'Press E to pick up':'Press E to talk to the Keeper';return close}document.getElementById('prompt').textContent='Press E to interact';return null}
