function special(){if(!running||paused||state.st<22)return;state.st-=22;player.cast=.23;playTone(540,.25);let dir={x:player.faceX,y:player.faceY};projectiles.push({x:player.x+dir.x*20,y:player.y+dir.y*20,vx:dir.x*550,vy:dir.y*550,life:1.6,enemy:false,damage:47});}
function dodge(){if(!running||paused||state.st<20||player.dodge>0)return;state.st-=20;player.dodge=.32;player.invuln=.45;player.vx=player.faceX*520;player.vy=player.faceY*520;burst(player.x,player.y,'#cad7a4',5)}
