function damagePlayer(n){if(player.invuln>0)return;state.hp-=n;player.invuln=.7;document.getElementById('flash').classList.add('on');setTimeout(()=>document.getElementById('flash').classList.remove('on'),110);playTone(90,.18);if(state.hp<=0){state.hp=0;showToast('You were overcome · restored at Hearthmere');setTimeout(()=>{player.x=430;player.y=970;state.hp=state.maxHp;state.st=state.maxSt;saveGame()},700)}updateUI()}
function updateEnemies(dt){for(const e of enemies){if(e.dead)continue;e.phase+=dt;e.cool-=dt;e.flash=Math.max(0,e.flash-dt);let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy),aggro=e.type==='guardian'?420:250;e.alert=e.alert||d<aggro;if(e.alert&&d>48){let speed=e.type==='guardian'?78:e.type==='brute'?70:95;e.x+=dx/d*speed*dt;e.y+=dy/d*speed*dt}else if(e.alert&&d<=52&&e.cool<=0){e.cool=e.type==='guardian'?1.1:1.45;if(e.type==='guardian'&&d>135){let a=Math.atan2(dy,dx);projectiles.push({x:e.x,y:e.y,vx:Math.cos(a)*230,vy:Math.sin(a)*230,life:2,enemy:true,damage:15})}else{if(player.invuln<=0)damagePlayer(e.type==='guardian'?20:e.type==='brute'?16:10);let a=Math.atan2(dy,dx);player.vx+=Math.cos(a)*110;player.vy+=Math.sin(a)*110}}else if(!e.alert){e.x=e.homeX+Math.cos(e.phase*.65)*32;e.y=e.homeY+Math.sin(e.phase*.8)*24}}}
