function update(dt){if(!running||paused)return;worldTime+=dt;player.invuln=Math.max(0,player.invuln-dt);player.attack=Math.max(0,player.attack-dt);player.dodge=Math.max(0,player.dodge-dt);player.cast=Math.max(0,player.cast-dt);player.st=Math.min(player.maxSt,player.st+dt*13);let mx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+(touchMove.x||0),my=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+(touchMove.y||0),mag=Math.hypot(mx,my);if(mag>1){mx/=mag;my/=mag}let speed=(keys.ShiftLeft||keys.ShiftRight?240:158);if(mag>0){player.faceX=mx;player.faceY=my;player.step+=dt*8;if(keys.ShiftLeft||keys.ShiftRight){if(state.st>0){state.st=Math.max(0,state.st-dt*18);speed=240}else speed=158}}let targetX=mx*speed,targetY=my*speed;if(player.dodge>0){targetX=player.vx;targetY=player.vy}else{player.vx=mix(player.vx,targetX,Math.min(1,dt*11));player.vy=mix(player.vy,targetY,Math.min(1,dt*11))}player.x=clamp(player.x+player.vx*dt,40,WORLD-40);player.y=clamp(player.y+player.vy*dt,40,WORLD-40);if(player.dodge<=0){player.vx=mix(player.vx,0,Math.min(1,dt*3));player.vy=mix(player.vy,0,Math.min(1,dt*3))}camera.x=mix(camera.x,player.x,Math.min(1,dt*5));camera.y=mix(camera.y,player.y,Math.min(1,dt*5));updateEnemies(dt);updateProjectiles(dt);for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96;p.life-=dt;if(p.life<=0)particles.splice(i,1)}for(let i=drops.length-1;i>=0;i--){if(dist(player,drops[i])<24){inventory[drops[i].kind==='coin'?'coins':'herbs']+=drops[i].amount||1;drops.splice(i,1)}}weather=Math.max(0,weather+dt*(Math.random()<.001?-1:Math.random()<.001?1:0));updateLocation();updateQuest();}
