let touchMove={x:0,y:0};
function saveGame(){try{localStorage.setItem('wildbound-save',JSON.stringify({player:{x:player.x,y:player.y},state,inventory,shards:shards.map(s=>s.got),enemies:enemies.map(e=>({hp:e.hp,dead:e.dead})),time:worldTime}));showToast('Journey saved')}catch{showToast('Save unavailable in this browser')}}
function loadGame(){try{let d=JSON.parse(localStorage.getItem('wildbound-save')||'null');if(!d)return false;player.x=d.player.x;player.y=d.player.y;Object.assign(state,d.state);Object.assign(inventory,d.inventory);worldTime=d.time||0;if(d.shards)d.shards.forEach((v,i)=>{if(shards[i])shards[i].got=v});if(d.enemies)d.enemies.forEach((v,i)=>{if(enemies[i]){enemies[i].hp=v.hp;enemies[i].dead=v.dead}});camera.x=player.x;camera.y=player.y;updateQuest();return true}catch{return false}}
function openPanel(type){const panel=document.getElementById('panel'),eyebrow=document.getElementById('panelEyebrow'),title=document.getElementById('panelTitle'),body=document.getElementById('panelBody');panel.classList.add('open');if(type==='map'){eyebrow.textContent='THE GREENWARD';title.textContent='Field Map';body.innerHTML='<p class="sub">A hand-drawn chart of the known wilds. Gold marks the sunshards; red marks danger.</p><canvas class="maplarge" id="largeMap"></canvas><p class="sub">✦ Sunshard &nbsp; ● You &nbsp; ◆ Hearthmere &nbsp; ◉ Drowned Shrine</p>';drawLargeMap()}else{eyebrow.textContent='TRAVELER’S SATCHEL';title.textContent='Inventory';body.innerHTML=`<p class="sub">A few useful things for a long road. You carry what you find.</p><div class="inventory-grid"><div class="item"><span>✦</span><b>Sunshards</b><small>${inventory.shards} / 3 recovered</small></div><div class="item"><span>◉</span><b>Silver coins</b><small>${inventory.coins} in your purse</small></div><div class="item"><span>✿</span><b>Wild herbs</b><small>${inventory.herbs} gathered</small></div><div class="item"><span>⚗</span><b>Wild tonics</b><small>${inventory.potions} · restores 45 vitality</small></div><div class="item"><span>✧</span><b>Renown · Level ${state.level}</b><small>${state.xp} renown · ${state.kills} foes defeated</small></div><div class="item"><span>⚔</span><b>Ironwood blade</b><small>Reliable, well-balanced</small></div></div><div style="display:flex;gap:9px;flex-wrap:wrap"><button class="action" id="drinkBtn">USE TONIC</button><button class="action" id="saveBtn">SAVE JOURNEY</button><button class="action" id="loadBtn">LOAD SAVE</button></div><p class="sub" style="margin-top:15px">Progress saves locally on this device. Your journey is yours to continue.</p>`;document.getElementById('drinkBtn').onclick=()=>{usePotion();openPanel('inventory')};document.getElementById('saveBtn').onclick=saveGame;document.getElementById('loadBtn').onclick=()=>{if(loadGame())showToast('Journey restored');else showToast('No saved journey found');openPanel('inventory')}}}
function drawLargeMap(){let c=document.getElementById('largeMap');if(!c)return;let r=c.getBoundingClientRect();c.width=r.width*DPR;c.height=r.height*DPR;let g=c.getContext('2d');g.scale(DPR,DPR);let w=r.width,h=r.height;g.fillStyle='#213b32';g.fillRect(0,0,w,h);g.strokeStyle='#5e9281';g.lineWidth=24;g.beginPath();for(let y=0;y<=h;y+=5){let wy=y/h*WORLD,x=(1180+230*Math.sin(wy/320)+80*Math.sin(wy/105))/WORLD*w;if(y===0)g.moveTo(x,y);else g.lineTo(x,y)}g.stroke();g.strokeStyle='#b9a576';g.lineWidth=5;g.beginPath();g.moveTo(430/WORLD*w,970/WORLD*h);g.bezierCurveTo(700/WORLD*w,870/WORLD*h,990/WORLD*w,1070/WORLD*h,1570/WORLD*w,950/WORLD*h);g.lineTo(1950/WORLD*w,1920/WORLD*h);g.stroke();for(const l of landmarks){g.fillStyle=l.type==='village'?'#d8bd78':l.type==='shrine'?'#7ed0b3':'#abb69b';g.beginPath();g.arc(l.x/WORLD*w,l.y/WORLD*h,l.type==='village'?7:9,0,7);g.fill()}for(const s of shards)if(!s.got){g.fillStyle='#f2d47d';g.beginPath();g.arc(s.x/WORLD*w,s.y/WORLD*h,5,0,7);g.fill()}for(const e of enemies)if(!e.dead){g.fillStyle='#db8060';g.beginPath();g.arc(e.x/WORLD*w,e.y/WORLD*h,3,0,7);g.fill()}g.fillStyle='#fff0c2';g.beginPath();g.arc(player.x/WORLD*w,player.y/WORLD*h,5,0,7);g.fill();g.strokeStyle='#f4dfa1';g.lineWidth=1;g.strokeRect(1,1,w-2,h-2)}
function togglePause(){if(!running)return;paused=!paused;let panel=document.getElementById('panel');if(paused){panel.classList.add('open');document.getElementById('panelEyebrow').textContent='A MOMENT OF QUIET';document.getElementById('panelTitle').textContent='Journey Paused';document.getElementById('panelBody').innerHTML='<p class="sub">Take a breath, traveler. Your progress saves automatically as you explore.</p><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:20px"><button class="action" id="resumeBtn">RESUME JOURNEY</button><button class="action" id="pauseSave">SAVE JOURNEY</button><button class="action" id="pauseInv">SATCHEL</button></div>';document.getElementById('resumeBtn').onclick=togglePause;document.getElementById('pauseSave').onclick=saveGame;document.getElementById('pauseInv').onclick=()=>{paused=false;openPanel('inventory')}}else panel.classList.remove('open')}
function activate(){if(!running){running=true;document.getElementById('titleOverlay').classList.remove('open');loadGame();last=performance.now();showToast('The wilds await. Find the sunshards.');if(soundOn)startMusic();return}if(paused)return;interact()}
let musicTimer=null,musicIndex=0;function startMusic(){if(!soundOn)return;try{if(!audio)audio=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();if(musicTimer)return;const notes=[196,246.94,293.66,246.94,220,261.63,329.63,261.63];musicTimer=setInterval(()=>{if(!soundOn||paused)return;let o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=notes[musicIndex++%notes.length];g.gain.setValueAtTime(.0001,audio.currentTime);g.gain.exponentialRampToValueAtTime(.012,audio.currentTime+.12);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+1.6);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+1.65)},760)}catch{}}
function toggleSound(){soundOn=!soundOn;document.getElementById('soundBtn').classList.toggle('active',soundOn);if(soundOn){startMusic();playTone(480,.12);showToast('Ambient music on')}else{if(musicTimer){clearInterval(musicTimer);musicTimer=null}showToast('Ambient music off')}}
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code==='Space')attack();if(e.code==='KeyQ')special();if(e.code==='KeyE')interact();if(e.code==='KeyF')usePotion();if(e.code==='ShiftLeft'||e.code==='ShiftRight')dodge();if(e.code==='KeyI')openPanel('inventory');if(e.code==='KeyM')openPanel('map');if(e.code==='Escape'){if(document.getElementById('panel').classList.contains('open')){document.getElementById('panel').classList.remove('open');if(paused)paused=false}else togglePause()}});addEventListener('keyup',e=>keys[e.code]=false);
document.getElementById('startBtn').onclick=activate;document.getElementById('mapBtn').onclick=()=>openPanel('map');document.getElementById('bagBtn').onclick=()=>openPanel('inventory');document.getElementById('soundBtn').onclick=toggleSound;document.getElementById('pauseBtn').onclick=togglePause;document.getElementById('closePanel').onclick=()=>{document.getElementById('panel').classList.remove('open');paused=false};document.getElementById('panel').addEventListener('click',e=>{if(e.target.id==='panel'){document.getElementById('panel').classList.remove('open');paused=false}});

